WITH filtered AS (SELECT id, reading_ts, temp_c, humidity, status_bits, firmware, ROUND(humidity * 100, 2) AS humidity_adjusted FROM device_readings WHERE reading_ts > DATE '2025-09-01') SELECT CASE WHEN temp_c >= 40.7 THEN 'LARGE' ELSE 'SMALL' END AS temp_c_tier, CASE WHEN status_bits >= 12 THEN 'PREMIUM' ELSE 'STANDARD' END AS status_bits_tier, CORR(temp_c, humidity) AS corr_temp_c_humidity, MIN(reading_ts) AS first_seen, MIN(humidity_adjusted) AS min_humidity_adjusted, DENSE_RANK() OVER (PARTITION BY CASE WHEN temp_c >= 40.7 THEN 'LARGE' ELSE 'SMALL' END ORDER BY CORR(temp_c, humidity) DESC) AS corr_temp_c_humidity_dense_rank FROM filtered GROUP BY CASE WHEN temp_c >= 40.7 THEN 'LARGE' ELSE 'SMALL' END, CASE WHEN status_bits >= 12 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY status_bits_tier DESC
